mapper.update:
update user_token_quota
set daily_used   = daily_used + #{totalTokens},
    monthly_used = monthly_used + #{totalTokens},
    total_used   = total_used + #{totalTokens}
where user_id = #{userId}

update user_token_quota
daily_limit = #{dailyLimit}, monthly_limit = #{monthlyLimit}, total_limit = #{totalLimit},
where user_id = #{userId}

update user_token_quota
set daily_used = 0, last_reset_daily = curdate()
where user_id = #{userId}

update user_token_quota
set monthly_used = 0, last_reset_monthly = #{month}
where user_id = #{userId}
